def flood_fill_adjacent(grid, start_val=2, new_val=3):
    """Fill all cells with start_val, plus 4-way neighbors, recursively"""
    output = [[grid[r][c] for c in range(5)] for r in range(4)]
    visited = [False]*5 for _ in range(4)]

    positions = []
    for r in range(4):
        for c in range(5):
            if grid[r][c] == start_val:
                positions.append((r,c))

    visited = [[False]*5 for _ in range(4)]
    for r, c in positions:
        visited[r][c] = True

    queue = deque(positions)
    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:  # 4-way
            nr, nc = r + dr, c + dc
            if 0 <= nr < 4 and 0 <= nc < 5 and not visited[nr][nc]:
                if output[nr][nc] == start_val or output[nr][nc] == new_val:
                    visited[nr][nc] = True
                    output[nr][nc] = new_val
                    queue.append((nr, nc))

    return output

